const fs = require('fs');
const path = require('path');
const { extractEntries } = require('./extractEntries');
const { flatToNested } = require('./flatToNested');

function processTranslations(apiResponse) {
  const translations = {};

  if (apiResponse.data && typeof apiResponse.data === 'object') {
    Object.keys(apiResponse.data).forEach((langCode) => {
      if (typeof apiResponse.data[langCode] === 'object') {
        translations[langCode] = apiResponse.data[langCode];
      }
    });
  } else {
    console.error('❌ API response does not match expected structure');
    console.log('Expected: { data: { "en-US": { ... }, "pt-BR": { ... } } }');
    console.log('Received:', JSON.stringify(apiResponse, null, 2));
  }

  return translations;
}

function saveFullResponse(apiResponse, outputDir) {
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  const dataPath = path.join(outputDir, 'data.json');
  fs.writeFileSync(dataPath, JSON.stringify(apiResponse, null, 2), 'utf8');
  console.log('✅ Full response saved: data.json');
}

function saveTranslationsAsJson(langCode, translations, outputDir, useDraftValues) {
  const extracted = extractEntries(translations, useDraftValues);

  if (Object.keys(extracted).length === 0) {
    console.warn(`⚠️  No translations found for ${langCode} in API response`);
    return null;
  }

  const nested = flatToNested(extracted);
  const jsonPath = path.join(outputDir, `${langCode}.json`);

  fs.writeFileSync(jsonPath, JSON.stringify(nested, null, 2), 'utf8');
  console.log(`✅ File generated: ${langCode}.json`);

  return jsonPath;
}

module.exports = {
  processTranslations,
  saveFullResponse,
  saveTranslationsAsJson,
};
